func newResourceExporter(svc *Service) *resourceExporter {
	return &resourceExporter{
		nameGen:     wordplay.GetRandomName,
		bucketSVC:   svc.bucketSVC,
		checkSVC:    svc.checkSVC,
		dashSVC:     svc.dashSVC,
