		t.Errorf("ParsePoint() len mismatch: got %v, exp %v", len(pts), exp)
	}

	if fields, err := pts[0].Fields(); err != nil {
		t.Fatal(err)
	} else if _, ok := fields["int"].(int64); !ok {
		t.Errorf("ParsePoint() int field mismatch: got %T, exp %T", fields["int"], int64(10))
