			t.Errorf("%d. ParsePoint() to string mismatch:\n got %v\n exp %v", i, got, tt.exp)
		}

		got = tt.pt.String()
		if tt.exp != got {
			t.Errorf("%d. NewPoint() to string mismatch:\n got %v\n exp %v", i, got, tt.exp)
		}
	}
}

