339:   write(chunk: string | TypescriptWriterCallback = '') {
340:     if (typeof chunk === 'string') {
341:       this.writer.write(chunk);
342:     } else if (typeof chunk === 'function') {
343:       chunk(this);
344:     }
345:   }
346: 
347:   end() {
348:     this.writer.end();
349:   }
