352: function getName(path: string | undefined): string | undefined {
353:   if (!path) {
354:     return undefined;
355:   }
356:   const parts = path.split('.');
357: 
358:   if (parts.length > 0) {
359:     return _.last(parts);
360:   } else {
361:     return undefined;
362:   }
363: }
