365: function checkExists<T>(t: T): NonNullable<T> {
366:   if (t === null) {
367:     throw new Error('Expected non-null reference, but got null');
368:   }
369:   return t as NonNullable<T>;
370: }
371: 
372: function getType(
373:   type: JsonSchema,
374:   schemas: Record<string, JsonSchema>
375: ): string | TypescriptWriterCallback {
376:   if (type.type === 'array') {
377:     const child = getType(checkExists(type.items), schemas);
378: 
379:     if (typeof child === 'string') {
380:       return `${child}[]`;
381:     } else if (typeof child === 'function') {
382:       return (writer: TypescriptTextWriter) => {
383:         writer.write('Array<');
384:         child(writer);
385:         writer.write('>');
386:       };
387:     } else {
388:       return '[]';
389:     }
390:   } else if (type.type === 'object' && type.properties) {
391:     return (writer: TypescriptTextWriter) => {
392:       writer.anonymousType(() => {
393:         _.forEach(type.properties, (property, propertyName) => {
394:           if (property.description) {
395:             writer.comment(formatComment(property.description));
396:           }
397:           writer.property(
398:             propertyName,
399:             getType(property, schemas),
400:             property.required || false
401:           );
402:         });
403: 
404:         if (type.additionalProperties) {
405:           writer.property(
406:             '[key: string]',
407:             getType(type.additionalProperties, schemas)
408:           );
409:         }
410:       });
411:     };
412:   } else if (type.type === 'object' && type.additionalProperties) {
413:     return (writer: TypescriptTextWriter) => {
414:       const child = getType(checkExists(type.additionalProperties), schemas);
415:       // Record<K, T> (workaround for https://github.com/Maxim-Mazurok/google-api-typings-generator/issues/206)
416:       writer.write('{ [P in string]: ');
417:       writer.write(child);
418:       writer.write(' }');
419:     };
420:   } else if (type.type) {
421:     const tsType = typesMap[type.type] || type.type;
422:     return type.repeated ? `${tsType} | ${tsType}[]` : tsType;
423:   } else if (type.$ref) {
424:     const referencedType = schemas[type.$ref];
425: 
426:     if (isEmptySchema(referencedType)) {
427:       return 'any';
428:     }
429: 
430:     return type.$ref;
431:   } else throw Error();
432: }
