434: function formatComment(comment: string) {
435:   if (!comment) return '';
436: 
437:   return comment;
438: }
439: 
440: function getMethodReturn(
441:   method: RestMethod,
442:   schemas: Record<string, JsonSchema>
443: ) {
444:   const name = schemas['Request'] ? 'client.Request' : 'Request';
445: 
446:   if (method.response) {
447:     const schema = schemas[checkExists(method.response.$ref)];
448: 
449:     if (schema && !_.isEmpty(schema.properties)) {
450:       return `${name}<${method.response.$ref}>`;
451:     } else {
452:       return `${name}<{}>`;
453:     }
454:   } else {
455:     return `${name}<void>`;
456:   }
457: }
