492:   /**
493:    * Creates a callback that writes request parameters.
494:    */
495:   private static createRequestParameterWriterCallback(
496:     parameters: Record<string, JsonSchema>,
497:     schemas: Record<string, JsonSchema>,
498:     ref?: string
499:   ) {
500:     return function requestParameterWriterCallback(
501:       writer: TypescriptTextWriter
502:     ) {
503:       writer.anonymousType(() => {
504:         _.forEach(parameters, (data, key) => {
505:           if (data.description) {
506:             writer.comment(formatComment(data.description));
507:           }
508: 
509:           writer.property(key, getType(data, schemas), Boolean(data.required));
510:         });
511: 
512:         if (ref) {
513:           writer.comment('Request body');
514:           writer.property('resource', ref, true);
515:         }
516:       });
517:     };
518:   }
