520:   /**
521:    * Writes specified resource definition.
522:    */
523:   private writeResources(
524:     out: TypescriptTextWriter,
525:     resources: Record<string, RestResource>,
526:     parameters: Record<string, JsonSchema> = {},
527:     schemas: Record<string, JsonSchema>
528:   ) {
529:     _.forEach(resources, (resource, resourceName) => {
530:       const resourceInterfaceName = getResourceTypeName(resourceName);
531: 
532:       if (resource.resources) {
533:         this.writeResources(out, resource.resources, parameters, schemas);
534:       }
535: 
536:       out.interface(resourceInterfaceName, () => {
537:         _.forEach(resource.methods, method => {
538:           if (method.description) {
539:             out.comment(formatComment(method.description));
540:           }
541: 
542:           const requestRef = method.request?.$ref;
543:           const requestParameters: Record<string, JsonSchema> = sortObject({
544:             ...parameters,
545:             ...method.parameters,
546:           });
547: 
548:           if (!requestParameters.resource || !requestRef) {
549:             // generate method(request)
550:             out.method(
551:               formatPropertyName(checkExists(getName(method.id))),
552:               [
553:                 {
554:                   parameter: 'request',
555:                   type: App.createRequestParameterWriterCallback(
556:                     requestParameters,
557:                     schemas,
558:                     requestRef
559:                   ),
560:                   required: Boolean(requestRef),
561:                 },
562:               ],
563:               getMethodReturn(method, schemas)
564:             );
565:           }
566: 
567:           if (requestRef) {
568:             // generate method(request, body)
569:             out.method(
570:               formatPropertyName(checkExists(getName(method.id))),
571:               [
572:                 {
573:                   parameter: 'request',
574:                   type: App.createRequestParameterWriterCallback(
575:                     requestParameters,
576:                     schemas
577:                   ),
578:                   required: true,
579:                 },
580:                 {
581:                   parameter: 'body',
582:                   type: requestRef,
583:                   required: true,
584:                 },
585:               ],
586:               getMethodReturn(method, schemas)
587:             );
588:           }
589:         });
590: 
591:         if (resource.resources) {
592:           _.forEach(resource.resources, (_, childResourceName) => {
593:             const childResourceInterfaceName = getResourceTypeName(
594:               childResourceName
595:             );
596:             out.property(childResourceName, childResourceInterfaceName);
597:           });
598:         }
599:       });
600:     });
601:   }
