603:   /// writes api description for specified JSON object
604:   private processApi(
605:     destinationDirectory: string,
606:     api: RestDescription,
607:     actualVersion: boolean,
608:     url: string
609:   ) {
610:     console.log(
611:       `Generating ${api.id} definitions... ${
612:         (api.labels && api.labels.join(', ')) || ''
613:       }`
614:     );
615: 
616:     const stream = fs.createWriteStream(
617:       path.join(destinationDirectory, 'index.d.ts')
618:     );
619:     const writer = new TypescriptTextWriter(
620:       new IndentedTextWriter(new StreamWriter(stream)),
621:       this.config.maxLineLength,
622:       this.config.bannedTypes
623:     );
624: 
625:     writer.writeLine(
626:       `// Type definitions for non-npm package ${api.title} ${
627:         api.version
628:       } ${parseVersion(checkExists(api.version))}`
629:     );
630:     writer.writeLine(`// Project: ${api.documentationLink}`);
631:     this.config.owners.forEach((owner, index) =>
632:       writer.writeLine(
633:         index === 0
634:           ? `// Definitions by: ${owner}`
635:           : `//                 ${owner}`
636:       )
637:     );
638: 
639:     writer.writeLine(
640:       '// Definitions: https://github.com/DefinitelyTyped/DefinitelyTyped'
641:     );
642:     writer.writeLine('// TypeScript Version: 2.8');
643:     writer.writeLine();
644:     writer.writeLine('// IMPORTANT');
645:     writer.writeLine(
646:       '// This file was generated by https://github.com/Maxim-Mazurok/google-api-typings-generator. Please do not edit it manually.'
647:     );
648:     writer.writeLine(
649:       '// In case of any problems please post issue to https://github.com/Maxim-Mazurok/google-api-typings-generator'
650:     );
651:     writer.writeLine(`// Generated from: ${url}`);
652:     writer.writeLine(`${revisionPrefix}${api.revision}`);
653:     writer.writeLine();
654:     writer.referenceTypes('gapi.client');
655: 
656:     // write main namespace
657:     writer.declareNamespace('gapi.client', () => {
658:       writer.comment(formatComment(`Load ${api.title} ${api.version}`));
659: 
660:       writer.method(
661:         'function load',
662:         [
663:           {parameter: 'name', type: `"${api.name}"`, required: true},
664:           {parameter: 'version', type: `"${api.version}"`, required: true},
665:         ],
666:         'PromiseLike<void>',
667:         true
668:       );
669: 
670:       writer.method(
671:         'function load',
672:         [
673:           {parameter: 'name', type: `"${api.name}"`, required: true},
674:           {parameter: 'version', type: `"${api.version}"`, required: true},
675:           {parameter: 'callback', type: '() => any', required: true},
676:         ],
677:         'void',
678:         true
679:       );
680: 
681:       // expose root resources to gapi.client namespace
682: 
683:       writer.endLine();
684: 
685:       writer.namespace(checkExists(api.name), () => {
686:         const schemas = checkExists(api.schemas);
687: 
688:         _.forEach(schemas, schema => {
689:           writer.interface(
690:             checkExists(schema.id),
691:             () => {
692:               if (schema.properties) {
693:                 _.forEach(schema.properties, (data, key) => {
694:                   if (data.description) {
695:                     writer.comment(formatComment(data.description));
696:                   }
697:                   writer.property(
698:                     key,
699:                     getType(data, schemas),
700:                     data.required || false
701:                   );
702:                 });
703:               }
704: 
705:               if (schema.additionalProperties) {
706:                 writer.property(
707:                   '[key: string]',
708:                   getType(schema.additionalProperties, schemas)
709:                 );
710:               }
711:             },
712:             isEmptySchema(schema)
713:           );
714:         });
715: 
716:         if (api.resources) {
717:           this.writeResources(writer, api.resources, api.parameters, schemas);
718: 
719:           _.forEach(api.resources, (_, resourceName) => {
720:             if (resourceName !== 'debugger') {
721:               writer.endLine();
722:               writer.writeLine(
723:                 `const ${resourceName}: ${getResourceTypeName(resourceName)};`
724:               );
725:             }
726:           });
727:         }
728:       });
729:     });
730: 
731:     writer.end();
732:   }
