734:   private request(url: string): Promise<DirectoryList> {
735:     return new Promise((resolve, reject) => {
736:       request(
737:         url,
738:         {
739:           gzip: true,
740:           ...(this.config.proxy ? {proxy: this.config.proxy.toString()} : {}),
741:         },
742:         (error, response, body) => {
743:           if (!error && response.statusCode === 200) {
744:             try {
745:               const api = JSON.parse(body) as DirectoryList;
746:               resolve(api);
747:             } catch (e) {
748:               console.error(
749:                 `Caught an error: ${e.message}; while parsing JSON from ${url}: "${body}"`
750:               );
751:               reject(error);
752:             }
753:           } else {
754:             console.error('Got an error: ', error);
755:             if (response && response.statusCode) {
756:               console.error(`with status code: ${response.statusCode}`);
757:             }
758:             console.error(`while fetching ${url}`);
759:             reject(error);
760:           }
761:         }
762:       );
763:     });
764:   }
