766:   async processService(
767:     url: string,
768:     actualVersion: boolean,
769:     newRevisionsOnly = false
770:   ) {
771:     let api;
772: 
773:     try {
774:       api = (await this.request(url)) as RestDescription;
775:     } catch (e) {
776:       console.warn(e);
777:       return;
778:     }
779: 
780:     if (!api.documentationLink) {
781:       return console.error(
782:         `No documentationLink found for ${api.id}, can't write required Project header, aborting`
783:       );
784:     }
785: 
786:     api = sortObject(api);
787:     api.name = api.name!.toLocaleLowerCase();
788:     api.version = api.version!.toLocaleLowerCase();
789: 
790:     const destinationDirectory = path.join(
791:       this.config.typesDirectory,
792:       getTypeDirectory(api.name, actualVersion ? null : api.version)
793:     );
794: 
795:     if (this.config.discoveryJsonDirectory) {
796:       fs.writeFileSync(
797:         join(
798:           this.config.discoveryJsonDirectory,
799:           `${basename(destinationDirectory)}.json`
800:         ),
801:         JSON.stringify(api)
802:       );
803:     }
804: 
805:     ensureDirectoryExists(destinationDirectory);
806:     const indexDTSPath = path.join(destinationDirectory, 'index.d.ts');
807: 
808:     if (newRevisionsOnly && fs.existsSync(indexDTSPath)) {
809:       if (!api.revision) {
810:         return console.error(`There's no revision in JSON: ${api.id}`);
811:       }
812: 
813:       let existingRevision, line;
814:       const liner = new LineByLine(indexDTSPath);
815:       while ((line = liner.next())) {
816:         line = line.toString();
817:         if (line.startsWith(revisionPrefix)) {
818:           const match = line.match(new RegExp(`^${revisionPrefix}(\\d+)$`));
819:           if (match !== null && match.length === 2) {
820:             existingRevision = Number(match[1]);
821:             break;
822:           }
823:         }
824:       }
825: 
826:       if (!existingRevision) {
827:         return console.error(
828:           `Can't find previous revision in index.d.ts: ${api.id}`
829:         );
830:       }
831: 
832:       const newRevision = Number(api.revision);
833:       if (existingRevision > newRevision) {
834:         return console.warn(
835:           `Local revision ${existingRevision} is more recent than fetched ${newRevision}, skipping ${api.id}`
836:         );
837:       }
838:     }
839: 
840:     await this.processApi(destinationDirectory, api, actualVersion, url);
841: 
842:     const templateData = {...api, actualVersion};
843: 
844:     readmeTpl.write(path.join(destinationDirectory, 'readme.md'), templateData);
845:     tsconfigTpl.write(
846:       path.join(destinationDirectory, 'tsconfig.json'),
847:       templateData
848:     );
849:     tslintTpl.write(
850:       path.join(destinationDirectory, 'tslint.json'),
851:       templateData
852:     );
853: 
854:     this.writeTests(destinationDirectory, api);
855:   }
