857:   private writePropertyValue(
858:     scope: TypescriptTextWriter,
859:     api: RestDescription,
860:     property: JsonSchema
861:   ) {
862:     switch (property.type) {
863:       case 'number':
864:       case 'integer':
865:         scope.write('42');
866:         break;
867:       case 'boolean':
868:         scope.write('true');
869:         break;
870:       case 'string':
871:         scope.write('"Test string"');
872:         break;
873:       case 'array':
874:         this.writeArray(scope, api, checkExists(property.items));
875:         break;
876:       case 'object':
877:         this.writeObject(scope, api, property);
878:         break;
879:       case 'any':
880:         scope.write('42');
881:         break;
882:       default:
883:         throw new Error(`Unknown scalar type ${property.type}`);
884:     }
885:   }
