887:   private writeArray(
888:     scope: TypescriptTextWriter,
889:     api: RestDescription,
890:     items: JsonSchema
891:   ) {
892:     const schemaName = items.$ref;
893:     if (schemaName && this.seenSchemaRefs.has(schemaName)) {
894:       // Break out of recursive reference by writing undefined
895:       scope.write('undefined');
896:       return;
897:     }
898: 
899:     scope.scope(
900:       () => {
901:         scope.newLine('');
902:         if (schemaName) {
903:           this.writeSchemaRef(scope, api, schemaName);
904:         } else {
905:           this.writePropertyValue(scope, api, items);
906:         }
907:       },
908:       '[',
909:       ']'
910:     );
911:   }
