913:   private writeObject(
914:     scope: TypescriptTextWriter,
915:     api: RestDescription,
916:     object: JsonSchema
917:   ) {
918:     const schemaName = object.additionalProperties?.$ref;
919:     if (schemaName && this.seenSchemaRefs.has(schemaName)) {
920:       scope.write('undefined');
921:       return;
922:     }
923:     if (object.properties) {
924:       // If the object has properties, only write that structure
925:       scope.scope(() => {
926:         this.writeProperties(scope, api, object.properties!);
927:       });
928:       return;
929:     } else if (object.additionalProperties) {
930:       // Otherwise, we have a Record<K, V> and we should write a placeholder key
931:       scope.scope(() => {
932:         scope.newLine('A: ');
933:         if (schemaName) {
934:           this.writeSchemaRef(scope, api, schemaName);
935:         } else {
936:           this.writePropertyValue(scope, api, object.additionalProperties!);
937:         }
938:       });
939:     } else {
940:       this.writePropertyValue(scope, api, object);
941:     }
942:   }
