944:   // Performs a lookup of the specified interface/schema type and recursively generates stubbed values
945:   private writeSchemaRef(
946:     scope: TypescriptTextWriter,
947:     api: RestDescription,
948:     schemaName: string
949:   ) {
950:     if (this.seenSchemaRefs.has(schemaName)) {
951:       // Break out of recursive reference by writing undefined
952:       scope.write('undefined');
953:       return;
954:     }
955: 
956:     const schema = checkExists(api.schemas)[schemaName];
957:     if (!schema) {
958:       throw new Error(
959:         `Attempted to generate stub for unknown schema '${schemaName}'`
960:       );
961:     }
962: 
963:     this.seenSchemaRefs.add(schemaName);
964:     this.writeObject(scope, api, schema);
965:     this.seenSchemaRefs.delete(schemaName);
966:   }
