968:   private writeProperties(
969:     scope: TypescriptTextWriter,
970:     api: RestDescription,
971:     record: Record<string, JsonSchema>
972:   ) {
973:     _.forEach(record, (parameter, name) => {
974:       scope.newLine(`${formatPropertyName(name)}: `);
975:       if (parameter.type === 'object') {
976:         this.writeObject(scope, api, parameter);
977:       } else if (parameter.$ref) {
978:         this.writeSchemaRef(scope, api, parameter.$ref);
979:       } else {
980:         this.writePropertyValue(scope, api, parameter);
981:       }
982:       scope.endLine(',');
983:     });
984:   }
