986:   private writeResourceTests(
987:     scope: TypescriptTextWriter,
988:     api: RestDescription,
989:     ancestors: string,
990:     resourceName: string,
991:     resource: RestResource
992:   ) {
993:     _.forEach(resource.methods, (method, methodName) => {
994:       scope.comment(method.description);
