997:       const params: Record<string, JsonSchema> | undefined = method.parameters;
998:       const ref = method.request?.$ref;
999: 
1000:       if (params) {
1001:         scope.scope(() => {
1002:           this.writeProperties(scope, api, params);
1003:         });
1004:       }
1005: 
1006:       if (ref) {
1007:         if (!params) {
1008:           scope.write('{} ');
1009:         }
1010: 
1011:         scope.write(', ');
1012: 
1013:         this.writeSchemaRef(scope, api, ref);
1014:       }
1015: 
1016:       scope.endLine(');');
1017: 
1018:       _.forEach(resource.resources, (subResource, subResourceName) => {
1019:         this.writeResourceTests(
1020:           scope,
1021:           api,
1022:           `${ancestors}.${resourceName}`,
1023:           subResourceName,
1024:           subResource
1025:         );
1026:       });
1027:     });
1028:   }
