Added default label layout configurations for line, area, column, and bar chart types to automatically apply sensible label positioning strategies when users enable labels without specifying layout details. Modified the label functions in each chart's adaptor to inject appropriate layout arrays including boundary limits, position adjustments, overlap hiding, and color adjustments. Created comprehensive test cases to verify default layouts are applied correctly and can be overridden by user configurations. Cleaned up test files by removing debug code and ensuring all test cases properly destroy chart instances.

The product view tracking event fails to trigger correctly when navigating from a product listing page due to reliance on an outdated route object. Update the event handler to validate the current page context using the browser's location information instead of the initial route parameter. Increment the module version to reflect this correction.

--- lib/nacelle-klaviyo-plugin.js ---
import Vue from 'vue'
import KlaviyoForm from './nacelle/integrations/KlaviyoForm.vue'
import KlaviyoEmbedForm from './nacelle/integrations/KlaviyoEmbedForm.vue'
Vue.component('klaviyo-form', KlaviyoForm)
Vue.component('klaviyo-embed-form', KlaviyoEmbedForm)

const viewedProduct = (product) => {
  if (typeof window !== 'undefined') {
    const _learnq = window._learnq || []
    const item = {
      Name: product.title,
      ProductID: Buffer.from(product.pimSyncSourceProductId, 'base64')
        .toString('binary')
        .split('/')
        .pop(),
      Categories: product.tags,
      ImageURL: product.featuredMedia.src,
      URL: `${window.location.origin}/products/${product.handle}`,
      Brand: product.vendor,
      Price: product.priceRange.max,
      CompareAtPrice: product.variants
        .map((variant) => variant.compareAtPrice)
        .sort()
        .pop()
    }

    _learnq.push(['track', 'Viewed Product', item])
    _learnq.push([
      'trackViewedItem',
      {
        Title: item.Name,
        ItemId: item.ProductID,
        Categories: item.Categories,
        ImageUrl: item.ImageURL,
        Url: item.URL,
        Metadata: {
          Brand: item.Brand,
          Price: item.Price,
          CompareAtPrice: item.CompareAtPrice
        }
      }
    ])
  }
}

const addedToCart = (product) => {
  if (typeof window !== 'undefined') {
    const _learnq = window._learnq || []
    const item = {
      Name: product.title,
      ProductID: product.variant.id,
      Categories: product.tags,
      ImageURL: product.variant.featuredMedia.src,
      URL: `${window.location.origin}/products/${product.handle}`,
      Brand: product.vendor,
      Price: product.variant.price,
      CompareAtPrice: product.variant.compareAtPrice
    }

    _learnq.push(['track', 'Added to Cart', item])
  }
}

const setCustomer = (customer) => {
  if (typeof window !== 'undefined') {
    const _learnq = window._learnq || []
    if (customer.email) {
      _learnq.push([
        'identify',
        {
          $email: customer.email
        }
      ])
    }
  }
}

export default ({ store, route }) => {
  store.subscribe((mutation, state) => {
    const { type, payload } = mutation
    if (type === 'events/addEvent' && payload.eventType === 'productView') {
      viewedProduct(payload.product)
    }

    //! Caters to older versions of Nuxt starter's event dispatcher
    if (type === 'events/addEvent' && payload.eventType === 'PRODUCT_VIEW') {
      const { product } = payload.payload
      if (product && route.path.includes(product.handle)) {
        viewedProduct(product)
      }
    }

    if (type === 'cart/addLineItemMutation') {
      addedToCart(payload)
    }

    if (type === 'account/setCustomer') {
      setCustomer(payload)
    }
  })
}

