To wrap up:

Removed the stale route argument from the plugin initialization and replaced the path validation logic with a direct check against the browser's location href. Added a server-side rendering guard to prevent errors when accessing window properties during hydration. Updated the package version to reflect the fix for the product view event tracking.

Extend the object watching functionality to allow users to configure which properties should be excluded from triggering change callbacks. Currently, all property modifications are detected and reported, but there are legitimate cases where certain properties should be ignored - particularly framework-specific metadata properties that get automatically added to objects. The implementation should avoid hardcoding specific property names and instead provide flexible configuration options. Users should be able to specify exact property keys to ignore via an array, or ignore all properties starting with an underscore through a boolean flag. Update the type definitions to reflect the new options, document them in the readme, and add comprehensive tests covering property assignment, definition, and deletion for the new ignore behaviors.

(Repository: sindresorhus/on-change — Watch an object or array for changes)

--- index.js ---
'use strict';

const PATH_SEPARATOR = '.';
const TARGET = Symbol('target');
const UNSUBSCRIBE = Symbol('unsubscribe');

const isPrimitive = value => value === null || (typeof value !== 'object' && typeof value !== 'function');

const isBuiltinWithoutMutableMethods = value => value instanceof RegExp || value instanceof Number;

const isBuiltinWithMutableMethods = value => value instanceof Date;

const isSameDescriptor = (a, b) => {
	return a !== undefined && b !== undefined &&
		Object.is(a.value, b.value) &&
		(a.writable || false) === (b.writable || false) &&
		(a.enumerable || false) === (b.enumerable || false) &&
		(a.configurable || false) === (b.configurable || false);
};

const concatPath = (path, property) => {
	if (property && property.toString) {
		if (path) {
			path += PATH_SEPARATOR;
		}

		path += property.toString();
	}

	return path;
};

const walkPath = (path, callback) => {
	let index;

	while (path) {
		index = path.indexOf(PATH_SEPARATOR);

		if (index === -1) {
			index = path.length;
		}

		callback(path.slice(0, index));

		path = path.slice(index + 1);
	}
};

const shallowClone = value => {
	if (Array.isArray(value)) {
		return value.slice();
	}

	return Object.assign({}, value);
};

const onChange = (object, onChange, options = {}) => {
	const proxyTarget = Symbol('ProxyTarget');
	let inApply = false;
	let changed = false;
	let applyPath;
	let applyPrevious;
	let isUnsubscribed = false;
	const equals = options.equals || Object.is;
	let propCache = new WeakMap();
	let pathCache = new WeakMap();
	let proxyCache = new WeakMap();

	const handleChange = (path, property, previous, value) => {
		if (isUnsubscribed) {
			return;
		}

		if (!inApply) {
			onChange(concatPath(path, property), value, previous);
			return;
		}

		if (inApply && applyPrevious && previous !== undefined && value !== undefined && property !== 'length') {
			let item = applyPrevious;

			if (path !== applyPath) {
				path = path.replace(applyPath, '').slice(1);

				walkPath(path, key => {
					item[key] = shallowClone(item[key]);
					item = item[key];
				});
			}

			item[property] = previous;
		}

		changed = true;
	};

	const getOwnPropertyDescriptor = (target, property) => {
		let props = propCache !== null && propCache.get(target);

		if (props) {
			props = props.get(property);
		}

		if (props) {
			return props;
		}

		props = new Map();
		propCache.set(target, props);

		let prop = props.get(property);

		if (!prop) {
			prop = Reflect.getOwnPropertyDescriptor(target, property);
			props.set(property, prop);
		}

		return prop;
	};

	const invalidateCachedDescriptor = (target, property) => {
		const props = propCache ? propCache.get(target) : undefined;

		if (props) {
			props.delete(property);
		}
	};

	const buildProxy = (value, path) => {
		if (isUnsubscribed) {
			return value;
		}

		pathCache.set(value, path);

		let proxy = proxyCache.get(value);

		if (proxy === undefined) {
			proxy = new Proxy(value, handler);
			proxyCache.set(value, proxy);
		}

		return proxy;
	};

	const unsubscribe = target => {
		isUnsubscribed = true;
		propCache = null;
		pathCache = null;
		proxyCache = null;

		return target;
	};

