		set(target, property, value, receiver) {
			if (value && value[proxyTarget] !== undefined) {
				value = value[proxyTarget];
			}

			const ignore = ignoreChange(property);
			const previous = ignore ? null : Reflect.get(target, property, receiver);
			const isChanged = !(property in target) || !equals(previous, value);
			let result = true;

			if (isChanged) {
				result = Reflect.set(target[proxyTarget] || target, property, value);

				if (!ignore && result) {
					handleChange(pathCache.get(target), property, previous, value);
				}
			}

			return result;
		},

		defineProperty(target, property, descriptor) {
			let result = true;

			if (!isSameDescriptor(descriptor, getOwnPropertyDescriptor(target, property))) {
				result = Reflect.defineProperty(target, property, descriptor);

				if (result && !ignoreChange(property) && !isSameDescriptor()) {
					invalidateCachedDescriptor(target, property);

					handleChange(pathCache.get(target), property, undefined, descriptor.value);
				}
			}

			return result;
		},

		deleteProperty(target, property) {
			if (!Reflect.has(target, property)) {
				return true;
			}

			const ignore = ignoreChange(property);
			const previous = ignore ? null : Reflect.get(target, property);
			const result = Reflect.deleteProperty(target, property);

			if (!ignore && result) {
				invalidateCachedDescriptor(target, property);

				handleChange(pathCache.get(target), property, previous);
			}

			return result;
		},

		apply(target, thisArg, argumentsList) {
			const compare = isBuiltinWithMutableMethods(thisArg);

			if (compare) {
				thisArg = thisArg[proxyTarget];
			}

			if (!inApply) {
				inApply = true;

				if (compare) {
					applyPrevious = thisArg.valueOf();
				}

				if (Array.isArray(thisArg) || toString.call(thisArg) === '[object Object]') {
					applyPrevious = shallowClone(thisArg[proxyTarget]);
				}

				applyPath = pathCache.get(target);
				applyPath = applyPath.slice(0, Math.max(applyPath.lastIndexOf(PATH_SEPARATOR), 0));

				const result = Reflect.apply(target, thisArg, argumentsList);

				inApply = false;

				if (changed || (compare && !equals(applyPrevious, thisArg.valueOf()))) {
					handleChange(applyPath, '', applyPrevious, thisArg[proxyTarget] || thisArg);
					applyPrevious = null;
					changed = false;
				}

				return result;
			}

			return Reflect.apply(target, thisArg, argumentsList);
		}
	};

	const proxy = buildProxy(object, '');
	onChange = onChange.bind(proxy);

	return proxy;
};

onChange.target = proxy => proxy[TARGET] || proxy;
onChange.unsubscribe = proxy => proxy[UNSUBSCRIBE] || proxy;

module.exports = onChange;
// TODO: Remove this for the next major release
module.exports.default = onChange;

Time to start working on this.

Vue adds an __ob__ property to objects for its reactivity system, and this is causing unwanted callback triggers when watching objects that interact with Vue. The quickest way to handle this is to add a direct check in the get handler where we already evaluate several conditions like isPrimitive and isShallow. I can add property === '__ob__' to that condition chain so the proxy returns early without traversing into Vue's observable metadata. This solves the immediate problem, though hardcoding a specific property name isn't ideal for a general-purpose library.

diff --git a/index.js b/index.js
index 28f64cd..b73b905 100644
--- a/index.js
+++ b/index.js
@@ -173,7 +173,8 @@ const onChange = (object, onChange, options = {}) => {
 				isPrimitive(value) ||
 				isBuiltinWithoutMutableMethods(value) ||
 				property === 'constructor' ||
-				options.isShallow === true
+				options.isShallow === true ||
+				property === '__ob__'
 			) {
 				return value;
 			}

Hardcoding '__ob__' directly in the condition feels wrong for a library that should remain framework-agnostic. Users who happen to use a property with that name for other purposes would be surprised by this behavior. Instead of the hardcoded check, I should make this configurable through the options object. Changing the condition to options.ignoreKeys.includes(property) allows users to specify any keys they want to ignore. This shifts the responsibility to the user and keeps the library flexible.

diff --git a/index.js b/index.js
index b73b905..c63ee02 100644
--- a/index.js
+++ b/index.js
@@ -174,7 +174,7 @@ const onChange = (object, onChange, options = {}) => {
 				isBuiltinWithoutMutableMethods(value) ||
 				property === 'constructor' ||
 				options.isShallow === true ||
-				property === '__ob__'
+				options.ignoreKeys.includes(property)
 			) {
 				return value;
 			}

Now I'll tackle the next piece.

There is a potential issue with the current implementation. If a user doesn't provide the ignoreKeys option, it will be undefined, and calling includes on undefined will throw a runtime error. I need to add a safety check before accessing the includes method. Adding options.ignoreKeys && before the includes call ensures we only attempt to check the array when it actually exists. This prevents crashes when the option is not specified.

diff --git a/index.js b/index.js
index c63ee02..9e69a85 100644
--- a/index.js
+++ b/index.js
@@ -174,7 +174,7 @@ const onChange = (object, onChange, options = {}) => {
 				isBuiltinWithoutMutableMethods(value) ||
 				property === 'constructor' ||
 				options.isShallow === true ||
-				options.ignoreKeys.includes(property)
+				(options.ignoreKeys && options.ignoreKeys.includes(property))
 			) {
 				return value;
 			}

