--- readme.md ---
# on-change [![Build Status](https://travis-ci.org/sindresorhus/on-change.svg?branch=master)](https://travis-ci.org/sindresorhus/on-change)

> Watch an object or array for changes

It works recursively, so it will even detect if you modify a deep property like `obj.a.b[0].c = true`.

Uses the [`Proxy` API](https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Proxy).

## Install

```
$ npm install on-change
```

## Usage

```js
const onChange = require('on-change');

const object = {
	foo: false,
	a: {
		b: [
			{
				c: false
			}
		]
	}
};

let i = 0;
const watchedObject = onChange(object, function (path, value, previousValue) {
	console.log('Object changed:', ++i);
	console.log('this:', this);
	console.log('path:', path);
	console.log('value:', value);
	console.log('previousValue:', previousValue);
});

watchedObject.foo = true;
//=> 'Object changed: 1'
//=> 'this: {
//   	foo: true,
//   	a: {
//   		b: [
//   			{
//   				c: false
//   			}
//   		]
//   	}
//   }'
//=> 'path: "foo"'
//=> 'value: true'
//=> 'previousValue: false'

watchedObject.a.b[0].c = true;
//=> 'Object changed: 2'
//=> 'this: {
//   	foo: true,
//   	a: {
//   		b: [
//   			{
//   				c: true
//   			}
//   		]
//   	}
//   }'
//=> 'path: "a.b.0.c"'
//=> 'value: true'
//=> 'previousValue: false'

// Access the original object
onChange.target(watchedObject).foo = false;
// Callback isn't called

// Unsubscribe
onChange.unsubscribe(watchedObject);
watchedObject.foo = 'bar';
// Callback isn't called
```

## API

### onChange(object, onChange, options?)

Returns a version of `object` that is watched. It's the exact same object, just with some `Proxy` traps.

#### object

Type: `object`

Object to watch for changes.

#### onChange

Type: `Function`

Function that gets called anytime the object changes.

The function receives three arguments:
1. A path to the value that was changed. A change to `c` in the above example would return `a.b.0.c`.
2. The new value at the path.
3. The previous value at the path.

The context (this) is set to the original object passed to `onChange` (with Proxy).

#### options

Type: `object`

##### isShallow

Type: `boolean`<br>
Default: `false`

Deep changes will not trigger the callback. Only changes to the immediate properties of the original object.

##### equals

Type: `Function`<br>
Default: [`Object.is`](https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Object/is)

The function receives two arguments to be compared for equality. Should return `true` if the two values are determined to be equal. Useful if you only need a more loose form of equality.

##### ignoreSymbols

Type: `boolean`<br>
Default: false

Setting properties as `Symbol` won't trigger the callback.

### onChange.target(object)

Returns the original unwatched object.

#### object

Type: `object`

Object that is already being watched for changes.

### onChange.unsubscribe(object)

Cancels all future callbacks on a watched object and returns the original unwatched object.

#### object

Type: `object`

Object that is already being watched for changes.

## Use-case

I had some code that was like:

```js
const foo = {
	a: 0,
	b: 0
};

// …

foo.a = 3;
save(foo);

// …

foo.b = 7;
save(foo);

// …

foo.a = 10;
save(foo);
```

Now it can be simplified to:

```js
const foo = onChange({
	a: 0,
	b: 0
}, () => save(foo));

// …

foo.a = 3;

// …

foo.b = 7;

// …

foo.a = 10;
```

## Related

- [known](https://github.com/sindresorhus/known) - Allow only access to known object properties *(Uses `Proxy` too)*
- [negative-array](https://github.com/sindresorhus/negative-array) - Negative array index support `array[-1]` *(Uses `Proxy` too)*
- [statux](https://github.com/franciscop/state) - State manager *(Uses `Proxy` too)*
- [introspected](https://github.com/WebReflection/introspected) - Never-ending Proxy with multiple observers *(Uses `Proxy` too)*

## Maintainers

- [Sindre Sorhus](https://github.com/sindresorhus)
- [Darren Wright](https://github.com/DarrenPaulWright)

--- test.js ---
const onChange = require('.');
const displayValue = require('display-value');
const test = require('ava');

const testHelper = (t, object, options, callback) => {
	const last = {};

	const reset = () => {
		last.count = 0;
		last.thisArg = undefined;
		last.path = undefined;
		last.value = undefined;
		last.previous = undefined;
	};

	reset();

	const proxy = onChange(object, function (path, value, previous) {
		last.count++;
		last.thisArg = this;
		last.path = path;
		last.value = value;
		last.previous = previous;
	}, options);

	// eslint-disable-next-line max-params
	const verify = (count, thisArg, path, value, previous, fullObject) => {
		t.is(last.count, count);
		t.is(last.thisArg, thisArg);
		t.deepEqual(last.path, path);
		t.deepEqual(last.value, value);
		t.deepEqual(last.previous, previous);

		t.is(onChange.target(proxy), object);

		if (fullObject !== undefined) {
			t.deepEqual(object, fullObject);
			t.deepEqual(proxy, object);
		}
	};

	callback(proxy, verify, reset, last);

	onChange.unsubscribe(proxy);
};

const testValues = [
	null,
	undefined,
	'string',
	new RegExp('regExp1'), // eslint-disable-line prefer-regex-literals
	RegExp('regExp2'), // eslint-disable-line unicorn/new-for-builtins, prefer-regex-literals
	/regExp3/,
	true,
	false,
	1,
	'1',
	Number(2),
	new Number(3), // eslint-disable-line no-new-wrappers, unicorn/new-for-builtins
	Infinity,
	0,
	-0,
	NaN
];

test('main', t => {
	const object = {
		foo: false,
		bar: {
			a: {
				b: 0,
				c: [1, 2]
			}
		}
	};

	let callCount = 0;

	const proxy = onChange(object, () => {
		callCount++;
	});

	proxy.foo = true;
	t.is(proxy.constructor, Object);
	t.is(callCount, 1);

	Object.defineProperty(proxy, 'newProp', {
		value: '🦄'
	});
	t.is(callCount, 2);

	Object.assign(proxy, {foo: false});
	t.is(callCount, 3);

	delete proxy.foo;
	t.is(proxy.foo, undefined);
	t.is(callCount, 4);

	// Unwrap proxies on assignment
	const prev = object.bar.a;
	proxy.bar.a = proxy.bar.a; // eslint-disable-line no-self-assign
	t.is(object.bar.a, prev);
});

for (const [index1, value1] of testValues.entries()) {
	for (const [index2, value2] of testValues.entries()) {
		if (index1 !== index2) {
			test(`should detect value changes from ${displayValue(value1)} to ${displayValue(value2)}`, t => {
				const object = {
					a: value1,
					b: [1, 2, value1]
				};

				testHelper(t, object, {}, (proxy, verify) => {
					proxy.a = value2;
					t.is(proxy.a, value2);
					verify(1, proxy, 'a', value2, value1);

					proxy.a = value2;
					verify(1, proxy, 'a', value2, value1);

					proxy.b[2] = value2;
					t.is(proxy.b[2], value2);
					verify(2, proxy, 'b.2', value2, value1);

					proxy.b[2] = value2;
					verify(2, proxy, 'b.2', value2, value1);

					delete proxy.nonExistent;
					verify(2, proxy, 'b.2', value2, value1);

					delete proxy.b;
					t.is(proxy.b, undefined);
					verify(3, proxy, 'b', undefined, [1, 2, value2]);
				});
			});
		}
	}
}

