$match-suggestion-color: #999;
$match-suggestion-color-hover: #888;
$match-suggestion-wiki-extract-height: 85px;
$icon-fill-color-default: #999999;
$font-size-base: 15px;
$font-size-large: 1.1em;
$font-size-small: 0.8em;

// Mixins
@mixin placeholderAnimation {
  overflow: hidden;
  &::before {
    content: " ";
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 50%;
    z-index: 1;
    width: 500%;
    margin-left: -250%;
    animation: placeholderAnimation 0.8s linear infinite;
    background: linear-gradient(
        to right,
        rgba(#fff, 0) 46%,
        rgba(#fff, 0.35) 50%,
        rgba(#fff, 0) 54%
      )
      50% 50%;
  }
}

// Imports
@import "./Controls.scss";
@import "./Sidebar.scss";
@import "./SidebarMatch.scss";
@import "./Suggestion.scss";
@import "./SuggestionList.scss";
