    pub fn test_similarity_func(filename: &str, func: fn(&str, &str) -> f64) {
        let mut reader = csv::ReaderBuilder::new()
            .has_headers(false)
            .from_path(filename)
            .unwrap();
        let mut num_tested = 0;
        for result in reader.records() {
