+		{16, 19, 22, 25, 28},
+		{2, 5, 8, 11, 14},
+		{17, 20, 23, 26, 29},
+	}
+
+	for i, batch := range batches {
+
+		var reports []ScanReport
+		var err error
+		if i == len(batches)-1 {
+			reports = nil
+			err = errors.New("scan shard activity got error")
+		} else {
+			err = nil
+			for _, s := range batch {
+				reports = append(reports, ScanReport{
+					ShardID: s,
+					Stats: ScanStats{
+						EntitiesCount: 10,
