+			Shards: batch,
+		}).Return(reports, err)
+	}
+	s.env.ExecuteWorkflow(NewTestWorkflow, "test-workflow", ScannerWorkflowParams{
+		Shards: shards,
+	})
+	s.True(s.env.IsWorkflowCompleted())
