The Send method is the core of the client - it takes a Request with method, path, body, and headers, then constructs a retryable HTTP request and executes it. I need to join the path to the backend's base URL and add any custom headers from the request before sending.

diff --git a/core/internal/api/send.go b/core/internal/api/send.go
new file mode 100644
index 000000000..2c52e24ae
--- /dev/null
+++ b/core/internal/api/send.go
@@ -0,0 +1,31 @@
+package api
+
+import (
+	"fmt"
+	"net/http"
+
+	"github.com/hashicorp/go-retryablehttp"
+)
+
+// Sends an HTTP request to the W&B backend.
+func (client *Client) Send(req *Request) (*http.Response, error) {
+	retryableReq, err := retryablehttp.NewRequest(
+		req.Method,
+		client.backend.baseURL.JoinPath(req.Path).String(),
+		req.Body,
+	)
+	if err != nil {
+		return nil, fmt.Errorf("api: failed to create request: %w", err)
+	}
+
+	for headerKey, headerValue := range req.Headers {
+		retryableReq.Header.Add(headerKey, headerValue)
+	}
+
+	resp, err := client.retryableHTTP.Do(retryableReq)
+	if err != nil {
+		return nil, fmt.Errorf("api: failed sending: %w", err)
+	}
+
+	return resp, nil
+}

