+
+type RequestCopy struct {
+	Method string
+	URL    *url.URL
+	Body   string
+	Header http.Header
+}
+
+type RecordingServer struct {
+	*httptest.Server
+
+	requests *[]RequestCopy
+	mu       *sync.Mutex
+}
+
+// All requests recorded by the server.
+func (s *RecordingServer) Requests() []RequestCopy {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	return *s.requests
+}
+
+// Returns a server that records all requests made to it.
+func NewRecordingServer() *RecordingServer {
+	requests := new([]RequestCopy)
+	*requests = make([]RequestCopy, 0)
+
+	mu := &sync.Mutex{}
+	server := httptest.NewServer(http.HandlerFunc(
+		func(w http.ResponseWriter, r *http.Request) {
+			body, _ := io.ReadAll(r.Body)
+
+			mu.Lock()
+			defer mu.Unlock()
+
+			*requests = append(*requests,
+				RequestCopy{
+					Method: r.Method,
+					URL:    r.URL,
+					Body:   string(body),
+					Header: r.Header,
+				})
+
+			_, _ = w.Write([]byte("OK"))
+		}),
+	)
+
+	return &RecordingServer{server, requests, mu}
+}
