+package api
+
+import (
+	"net/http"
+)
+
+// A rate-limited HTTP transport for requests to the W&B backend.
+//
+// Implements [http.RoundTripper] for use as a transport for an HTTP client.
+type rateLimitedTransport struct {
+	backend  *Backend
+	delegate http.RoundTripper
+}
+
+// Rate-limits an HTTP transport for the W&B backend.
+func (backend *Backend) rateLimitedTransport(
+	delegate http.RoundTripper,
+) *rateLimitedTransport {
+	return &rateLimitedTransport{
+		backend:  backend,
+		delegate: delegate,
+	}
+}
+
+func (transport *rateLimitedTransport) RoundTrip(
+	req *http.Request,
+) (*http.Response, error) {
+	if err := transport.backend.rateLimiter.Wait(req.Context()); err != nil {
+		// Errors happen if:
+		//   - The request is canceled
+		//   - The rate limit exceeds the request deadline
+		return nil, err
+	}
+
+	return transport.delegate.RoundTrip(req)
+}

This work introduces a new api package that centralizes backend HTTP communication with built-in rate limiting, authentication, and retry logic. The implementation evolved from a simple client wrapper to a more sophisticated design with rate limiting at the HTTP transport layer using a token bucket algorithm. All existing clients (filestream and GraphQL) were migrated to use the new package, and obsolete code in the clients package was removed. The rate limiter uses hard-coded limits initially, with response header parsing planned for a follow-up.

