185: export type BaseObject = {
186:   effects?: Effect[];
187: };
188: 
189: export type RefObject = BaseObject & {
190:   type: 'ref';
191:   schema: oas31.ReferenceObject;
192:   schemaObject:
193:     | oas31.SchemaObject
194:     | oas31.ReferenceObject
195:     | oas30.ReferenceObject
196:     | oas30.SchemaObject
197:     | undefined;
198:   zodType: ZodType;
199: };
200: 
201: export type SchemaObject = BaseObject & {
202:   type: 'schema';
203:   schema: oas31.SchemaObject;
204: };
205: 
206: export type Schema = SchemaObject | RefObject;
207: 
208: export const createSchemaOrRef = <
209:   Output = unknown,
210:   Def extends ZodTypeDef = ZodTypeDef,
211:   Input = Output,
212: >(
213:   zodSchema: ZodType<Output, Def, Input>,
214:   state: SchemaState,
215:   onlyRef?: boolean,
216: ): Schema | undefined => {
217:   const component = state.components.schemas.get(zodSchema);
218:   const existingRef = createExistingRef(zodSchema, component, state);
219: 
220:   if (existingRef) {
221:     return existingRef;
222:   }
223: 
224:   const previous = zodSchema._def.zodOpenApi?.[previousSymbol]
225:     ? (createSchemaOrRef(
226:         zodSchema._def.zodOpenApi[previousSymbol],
227:         state,
228:         true,
229:       ) as RefObject | undefined)
230:     : undefined;
231: 
232:   const current =
233:     zodSchema._def.zodOpenApi?.[currentSymbol] &&
234:     zodSchema._def.zodOpenApi[currentSymbol] !== zodSchema
235:       ? (createSchemaOrRef(
236:           zodSchema._def.zodOpenApi[currentSymbol],
237:           state,
238:           true,
239:         ) as RefObject | undefined)
240:       : undefined;
241: 
242:   const ref = zodSchema._def.zodOpenApi?.openapi?.ref ?? component?.ref;
243:   if (ref) {
244:     return current
245:       ? createNewSchema({ zodSchema, previous: current, state })
246:       : createNewRef({ ref, zodSchema, previous, state });
247:   }
248: 
249:   if (onlyRef) {
250:     return previous ?? current;
251:   }
252: 
253:   return createNewSchema({ zodSchema, previous: previous ?? current, state });
254: };
255: 
256: export const createSchemaObject = <
257:   Output = unknown,
258:   Def extends ZodTypeDef = ZodTypeDef,
259:   Input = Output,
260: >(
261:   zodSchema: ZodType<Output, Def, Input>,
262:   state: SchemaState,
263:   subpath: string[],
264: ): Schema => {
265:   state.path.push(...subpath);
266:   const schema = createSchemaOrRef(zodSchema, state);
267: 
268:   if (!schema) {
269:     throw new Error('Schema does not exist');
270:   }
271:   state.path.pop();
272:   return schema;
273: };
274: 
275: export const createSchema = <
276:   Output = unknown,
277:   Def extends ZodTypeDef = ZodTypeDef,
278:   Input = Output,
279: >(
280:   zodSchema: ZodType<Output, Def, Input>,
281:   state: SchemaState,
282:   subpath: string[],
283: ): oas31.SchemaObject | oas31.ReferenceObject => {
284:   const schema = createSchemaObject(zodSchema, state, subpath);
285:   if (schema.effects) {
286:     verifyEffects(schema.effects, state);
287:   }
288:   return schema.schema;
289: };
